using System.Collections;
using System.Collections.Generic;
using Astrea.GameElements;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MultiStarAction", menuName = "Data/Battle/Battle Actions/Orion/MultiStar Action")]
public class MultiStarAction : BattleAction
{
	[Header("Cosmic Orb")]
	[SerializeField]
	private BattleAction cosmicOrbAction;

	[SerializeField]
	private StarAbility cosmicOrbStarAbility;

	[Header("Devotion Orb")]
	[SerializeField]
	private BattleAction devotionOrbAction;

	[SerializeField]
	protected StarAbility devotionOrbStarAbility;

	[Header("Karmic Orb")]
	[SerializeField]
	private BattleAction karmicOrbAction;

	[SerializeField]
	private StarAbility karmicOrbStarAbility;

	[Header("Knowledge Orb")]
	[SerializeField]
	private BattleAction knowledgeOrbAction;

	[SerializeField]
	protected StarAbility knowledgeOrbStarAbility;

	[Header("Star Ability Reference")]
	[SerializeField]
	protected StarAbilityReference starAbilityReference;

	[Header("Move Orbs")]
	[SerializeField]
	private bool moveOrbsAfterCasting;

	[SerializeField]
	[ShowIf("moveOrbsAfterCasting")]
	private int moveOrbAmount = 1;

	[SerializeField]
	[ShowIf("moveOrbsAfterCasting")]
	private BattleAction moveOrbsAction;

	[Header("Description")]
	[SerializeField]
	private bool oneOrbGoodAction;

	[SerializeField]
	[ShowIf("oneOrbGoodAction")]
	private StarAbility oneOrbGoodActionStarAbility;

	[SerializeField]
	[ShowIf("oneOrbGoodAction")]
	private bool enableOneOrbGoodCustomAmount;

	[SerializeField]
	[ShowIf("enableOneOrbGoodCustomAmount")]
	private int oneOrbGoodCustomAmount;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	[SerializeField]
	private bool vfxOnSource;

	[SerializeField]
	private bool spawnVFXCosmicOrb;

	[SerializeField]
	private bool spawnVFXDevotionOrb;

	[SerializeField]
	private bool spawnVFXKarmicOrb;

	[SerializeField]
	private bool spawnVFXKnowledgeOrb;

	public BattleAction CosmicOrbAction => cosmicOrbAction;

	public StarAbility CosmicOrbStarAbility => cosmicOrbStarAbility;

	public BattleAction DevotionOrbAction => devotionOrbAction;

	public StarAbility DevotionOrbStarAbility => devotionOrbStarAbility;

	public BattleAction KarmicOrbAction => karmicOrbAction;

	public StarAbility KarmicOrbStarAbility => karmicOrbStarAbility;

	public BattleAction KnowledgeOrbAction => knowledgeOrbAction;

	public StarAbility KnowledgeOrbStarAbility => knowledgeOrbStarAbility;

	public bool MoveOrbsAfterCasting => moveOrbsAfterCasting;

	public int MoveOrbAmount => moveOrbAmount;

	public BattleAction MoveOrbsAction => moveOrbsAction;

	public bool OneOrbGoodAction => oneOrbGoodAction;

	public StarAbility OneOrbGoodActionStarAbility => oneOrbGoodActionStarAbility;

	public bool EnableOneOrbGoodCustomAmount => enableOneOrbGoodCustomAmount;

	public int OneOrbGoodCustomAmount => oneOrbGoodCustomAmount;

	public bool AddHighlightToDescription(StarAbility starAbility)
	{
		return starAbilityReference.Value == starAbility;
	}

	public override DiceActionLogic GetDiceActionLogic(int actionValue = -1)
	{
		return GetBattleAction().GetDiceActionLogic(actionValue);
	}

	protected BattleAction GetBattleAction()
	{
		return GetBattleAction(starAbilityReference.Value);
	}

	private BattleAction GetBattleAction(StarAbility starAbilityReferenceToUse)
	{
		if (starAbilityReferenceToUse == cosmicOrbStarAbility)
		{
			return cosmicOrbAction;
		}
		if (starAbilityReferenceToUse == devotionOrbStarAbility)
		{
			return devotionOrbAction;
		}
		if (starAbilityReferenceToUse == karmicOrbStarAbility)
		{
			return karmicOrbAction;
		}
		return knowledgeOrbAction;
	}

	public BattleAction GetBattleActionForOneOrbGoodDescription()
	{
		return GetBattleAction(oneOrbGoodActionStarAbility);
	}

	public BattleAction GetBattleActionOtherOrbsOrbGoodDescription()
	{
		if (oneOrbGoodActionStarAbility != cosmicOrbStarAbility)
		{
			return cosmicOrbAction;
		}
		if (oneOrbGoodActionStarAbility != devotionOrbStarAbility)
		{
			return devotionOrbAction;
		}
		if (oneOrbGoodActionStarAbility != karmicOrbStarAbility)
		{
			return karmicOrbAction;
		}
		return knowledgeOrbAction;
	}

	private bool SpawnVFX()
	{
		if ((!(starAbilityReference.Value == cosmicOrbStarAbility) || !spawnVFXCosmicOrb) && (!(starAbilityReference.Value == devotionOrbStarAbility) || !spawnVFXDevotionOrb) && (!(starAbilityReference.Value == karmicOrbStarAbility) || !spawnVFXKarmicOrb))
		{
			if (starAbilityReference.Value == knowledgeOrbStarAbility)
			{
				return spawnVFXKnowledgeOrb;
			}
			return false;
		}
		return true;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay && SpawnVFX())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(target, amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		if (SpawnVFX())
		{
			SpawnVFX(GetVFXOwnerPosition(vfxOnSource ? source : target), 6f);
			if (IsVFXEnabled())
			{
				PlaySFX();
			}
		}
		GetBattleAction().CastTargetAmount(target, amount, source);
		CheckMoveOrb(source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator VFXCoroutine(GameObject target, int amount, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(vfxOnSource ? source : target), 6f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		yield return new WaitForSeconds(vfxDelay);
		GetBattleAction().CastTargetAmount(target, amount, source);
		CheckMoveOrb(source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		GetBattleAction().CastTarget(target, source);
		CheckMoveOrb(source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		GetBattleAction().AreaCastTargetAmount(targets, amount, source);
		CheckMoveOrb(source);
	}

	public override void Cast(GameObject source)
	{
		GetBattleAction().Cast(source);
		CheckMoveOrb(source);
	}

	public override void CastAmount(int actionValue, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay && SpawnVFX())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastAmountVFXCoroutine(actionValue, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		if (SpawnVFX())
		{
			SpawnVFX(GetVFXOwnerPosition(source), 6f);
			if (IsVFXEnabled())
			{
				PlaySFX();
			}
		}
		GetBattleAction().CastAmount(actionValue, source);
		CheckMoveOrb(source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator CastAmountVFXCoroutine(int actionValue, GameObject source)
	{
		if (SpawnVFX())
		{
			SpawnVFX(GetVFXOwnerPosition(source), 6f);
			if (IsVFXEnabled())
			{
				PlaySFX();
			}
		}
		yield return new WaitForSeconds(vfxDelay);
		GetBattleAction().CastAmount(actionValue, source);
		CheckMoveOrb(source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	protected void CheckMoveOrb(GameObject source)
	{
		if (moveOrbsAfterCasting)
		{
			moveOrbsAction.CastAmount(moveOrbAmount, source);
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
	}
}
